package org.apache.dubbo.remoting.transport.dispatcher;
import org.apache.dubbo.common.URL;
import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
import org.apache.dubbo.remoting.Channel;
import org.apache.dubbo.remoting.ChannelHandler;
import org.apache.dubbo.remoting.ExecutionException;
import org.apache.dubbo.remoting.RemotingException;
import org.apache.dubbo.remoting.exchange.Request;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.RejectedExecutionException;
public class WrappedChannelHandler {
    protected static final ErrorTypeAwareLogger logger = null;
    protected final ChannelHandler handler;
    public WrappedChannelHandler(ChannelHandler handler, URL url){ this.handler = handler; }
    public void connected(Channel channel) throws RemotingException {}
    public void disconnected(Channel channel) throws RemotingException {}
    public void received(Channel channel, Object message) throws RemotingException {}
    public void caught(Channel channel, Throwable exception) throws RemotingException {}
    public ExecutorService getPreferredExecutorService(Object msg){ return null; }
    public ExecutorService getSharedExecutorService(){ return null; }
    protected void sendFeedback(Channel channel, Request request, Throwable t) throws RemotingException {}
    protected void dispatchReceived(Channel channel, Object message) throws RemotingException {
        ExecutorService executor = getPreferredExecutorService(message);
        try {
            executor.execute(
                    new ChannelEventRunnable(channel, handler, ChannelEventRunnable.ChannelState.RECEIVED, message));
        } catch (Throwable t) {
            if (message instanceof Request && t instanceof RejectedExecutionException) {
                sendFeedback(channel, (Request) message, t);
                return;
            }
            throw new ExecutionException(message, channel, getClass() + " error when process received event .", t);
        }
    }
    protected void dispatchCaught(Channel channel, Throwable exception) throws RemotingException {
        ExecutorService executor = getSharedExecutorService();
        try {
            executor.execute(
                    new ChannelEventRunnable(channel, handler, ChannelEventRunnable.ChannelState.CAUGHT, exception));
        } catch (Throwable t) {
            throw new ExecutionException("caught event", channel, getClass() + " error when process caught event .", t);
        }
    }
}
EOF
